let editingPackage=null;
let state,view='overview',query='',filter='recent',actionPending=false;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=s=>{try{const u=new URL(s);return u.protocol==='https:'?esc(u.href):'#'}catch{return '#'}};
const link=(url,label)=>`<a href="${safeUrl(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
const date=s=>s?new Date(s).toLocaleString('en-NG',{timeZone:'Africa/Lagos',dateStyle:'medium',timeStyle:'short'}):'Not recorded';
const badge=(s,t='')=>`<span class="badge ${t}">${esc(s)}</span>`;
function notify(msg,error=false){
  const notice=$('#notice');notice.textContent=msg;notice.className=error?'error':'';notice.setAttribute('role',error?'alert':'status');
  const dialog=$('dialog[open]');if(dialog){let inline=$('#detail-feedback');if(!inline){inline=document.createElement('p');inline.id='detail-feedback';$('#detail-content').prepend(inline)}inline.textContent=msg;inline.className=error?'note error':'note';inline.setAttribute('role',error?'alert':'status');}
}
function operationMessage(result){
  if(result?.queued||result?.status==='queued')return result.message||'Waiting for the connected runner. This action has not executed.';
  if(result?.status==='blocked')return result.message||result.error||'This action is blocked and has not completed.';
  return result?.message||'Workspace updated.';
}
function notificationPanel(){const n=state.notifications;if(!n)return '';return '<div class="panel spacer"><h2>Run email notifications</h2><p>Recipient: '+esc(n.recipient)+'</p><p>'+esc(n.status==='connected'?'Notification sender connected. Each completed scheduled or manual discovery run attempts one summary email.':'Awaiting a dedicated Gmail send authorization. Emails are not active yet.')+'</p>'+(n.last_notification?'<p>Latest notification: '+esc(n.last_notification.status)+' · '+esc(n.last_notification.reason||'')+'</p>':'')+'</div>'}
function discoverySummary(){
  const run=(state.cloud_runs||[]).find(r=>r.kind==='hosted_discovery');if(!run)return '';
  const f=state.discovery_audit||run.funnel||{},failures=(run.source_results||[]).filter(s=>s.status!=='success'),breakdown=f.record_breakdown;
  const labels={hidden_by_owner:'Hidden by you',unrelated_role:'Unrelated job titles',duplicate_or_previously_applied:'Duplicates or previously applied',eligibility_or_pay_excluded:'Excluded by location or pay',not_remote:'Not remote',older_than_48_hours:'Older than 48 hours',needs_verification:'Still need evidence',confirmed:'Confirmed matches'};
  return `<div class="panel spacer"><h2>Latest discovery · ${esc(date(run.finished||run.started))}</h2><p>${esc(run.sources_verified??0)} of ${esc(run.sources_checked??0)} sources/searches completed.</p><p><strong>${esc(f.relevant_postings_observed??0)} posting records in this scan</strong> · ${esc(f.distinct_employers??0)} employers. This is a scan total, not a count of suitable openings.</p>${breakdown?`<div class="cards">${Object.entries(breakdown).map(([key,count])=>`<div class="check"><span>${esc(labels[key]||key)}</span><strong>${esc(count)}</strong></div>`).join('')}</div><p class="subtle">Each scanned record appears in one group above, using its current assessment. Hidden roles stay out of the job lists. The selected filter below shows a subset.</p>`:''}${!run.discovery_version?'<p class="note">This saved scan ran on an earlier discovery version. Refresh employer feeds to run the current version.</p>':''}<p class="subtle">A source check confirms a listing was read. It does not confirm Nigeria eligibility, salary or the employer-original publication date. Open Review for the evidence still missing.</p>${failures.length?`<p class="note">Sources not completed: ${failures.map(x=>esc(x.id)+': '+esc(x.error||x.status)).join('; ')}</p>`:''}<p class="subtle">${esc(f.coverage||'Configured public feeds; not a whole-internet search.')}</p><div class="row"><button data-filter-view="scan">Inspect visible records from this scan (${esc((f.relevant_postings_observed??0)-(breakdown?.hidden_by_owner||0))})</button><button data-filter-view="verification">Investigate leads awaiting verification</button><button data-filter-view="all">All visible records</button><button data-filter-view="hidden">Manage hidden roles</button></div></div>`;
}

async function api(path,body,retried=false){
  if(body&&(path==='run'||path==='discover')&&(!body.trigger||['full','discovery','shortlist'].includes(body.trigger)))body.request_id=body.request_id||crypto.randomUUID();
  const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json',...(state?.csrf?{'X-CSRF-Token':state.csrf}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(45000)});let data;
  try{data=await r.json()}catch{throw Error(r.status===401||r.status===403?'Your private HUNT session needs sign-in. Reopen your private login shortcut.':'HUNT received an unreadable response. A run may still be active; inspect Activity before starting another.')}
  if(r.status===403&&data.code==='CSRF_TOKEN_MISMATCH'&&body&&!retried){await refresh();return api(path,body,true)}
  if(!r.ok)throw Error(data.error||data.message||'Request failed ('+r.status+')');return data;
}
function rememberDiscovery(id){try{if(id)localStorage.setItem('hunt.activeDiscoveryRun',id);else localStorage.removeItem('hunt.activeDiscoveryRun')}catch{}}
function showDiscoveryProgress(task,transport='Live updates'){
 const host=typeof document==='undefined'?null:document.querySelector('#run-progress');if(!host)return;
 const p=task.progress||{},events=p.events||[],last=events.at(-1),terminal=['completed','failed','dispatch_uncertain'].includes(task.status);
 const signature=task.id+':'+task.status+':'+(last?.seq||0)+':'+transport;if(host.dataset.signature===signature)return;host.dataset.signature=signature;
 const labels={queued:'Starting',starting:'Starting',searching:'Searching',source_started:'Searching',source_completed:'Searching',source_failed:'Searching',source_skipped:'Searching',verifying_employer:'Checking employer evidence',collating:'Collating results',filtering:'Checking your criteria',saving:'Saving results',notifying:'Sending your summary',notification_sent:'Summary email sent',notification_failed:'Email needs attention',notification_blocked:'Email needs attention',notification_uncertain:'Email needs attention',done:'Done',failed:'Stopped'};
 host.hidden=false;host.className='live-progress';
 const warning=task.status==='failed'||task.result?.status==='partial',status=terminal?(warning?'Finished with issues':'Finished'):'Running';
 host.innerHTML='<div class="live-progress-head"><div><div class="overline">Discovery activity</div><h2 class="live-stage">'+esc(labels[last?.phase]||'Starting')+'</h2></div>'+badge(status,warning?'warn':'')+'</div><p>'+esc(last?.message||'Your request is saved. Waiting for runner updates.')+'</p><div class="live-counters"><span>Sources processed: <strong>'+esc(p.completed_sources??0)+' / '+esc(p.total_sources??'…')+'</strong></span><span>Posting records observed: <strong>'+esc(p.records_observed??0)+'</strong></span></div>'+(p.total_sources?'<progress aria-label="Sources processed" value="'+esc(Math.min(p.completed_sources||0,p.total_sources))+'" max="'+esc(p.total_sources)+'"></progress>':'')+'<div class="live-connection">'+esc(terminal?'Saved run activity':transport)+'</div><ol class="live-events" role="log" aria-live="polite" aria-relevant="additions">'+events.map(e=>'<li data-level="'+(/failed|blocked|uncertain|skipped/.test(e.phase)?'warning':e.phase==='done'||e.phase==='notification_sent'?'success':'info')+'"><time>'+esc(new Date(e.at).toLocaleTimeString('en-NG',{timeZone:'Africa/Lagos',hour12:false}))+'</time><span>'+esc(e.message)+'</span></li>').join('')+'</ol>';
 const log=host.querySelector('.live-events');if(log)log.scrollTop=log.scrollHeight;
}
function streamDiscovery(result){
 if(typeof EventSource==='undefined')return Promise.resolve(null);
 return new Promise((resolve,reject)=>{
  const stream=new EventSource('/api/discovery-events?id='+encodeURIComponent(result.run_id));let settled=false;
  const finish=(value,error)=>{if(settled)return;settled=true;stream.close();clearTimeout(timer);if(error)reject(error);else resolve(value)};
  const timer=setTimeout(()=>finish(null),180000);
  stream.addEventListener('progress',event=>{let task;try{task=JSON.parse(event.data)}catch{return finish(null)}showDiscoveryProgress(task);
   if(task.status==='completed'){rememberDiscovery(null);finish({result:task.result})}
   else if(['failed','dispatch_uncertain'].includes(task.status)){rememberDiscovery(null);finish(null,Error(task.message||'Discovery failed. Inspect the saved source results.'))}
  });
  stream.addEventListener('unavailable',()=>finish(null));stream.onerror=()=>finish(null);
 });
}
async function resumeDiscoveryProgress(){
 let id;try{id=localStorage.getItem('hunt.activeDiscoveryRun')}catch{return}if(!id||actionPending)return;
 actionPending=true;setActionControls(true);
 try{const result=await waitForDiscovery({background:true,run_id:id});await refresh();notify(operationMessage(result),result.status==='failed')}
 catch(error){notify(error.message,true)}finally{actionPending=false;setActionControls(false)}
}
async function waitForDiscovery(result){
  if(!result?.background||!result.run_id)return result;
  const deadline=Date.now()+180000;rememberDiscovery(result.run_id);showDiscoveryProgress({id:result.run_id,status:result.status||'queued',progress:result.progress});
  const streamed=await streamDiscovery(result);if(streamed)return streamed.result;
  while(Date.now()<deadline){const task=await api('discovery-task?id='+encodeURIComponent(result.run_id));showDiscoveryProgress(task,'Checking saved live updates');
    if(task.status==='completed'){rememberDiscovery(null);return task.result;}
    if(['failed','dispatch_uncertain'].includes(task.status)){rememberDiscovery(null);throw Error(task.message||'Discovery failed. Inspect the saved run in Activity.');}
    notify('Discovery is running. Follow the live activity below.');
    await new Promise(resolve=>setTimeout(resolve,2500));
  }
  return {status:'running',message:'Discovery continues in the cloud. Check Latest discovery and Activity for its saved result; completion is not yet confirmed.'};
}

async function refresh(){state=await api('state');render();}
function isFreshRemote(j){return !state.hosted||(j.within_discovery_window===true&&j.global_remote===true)}
function needsVerification(j){
  const a=j.assessment;
  if(j.hidden||!j.open||a.role_relevant===false||a.tier==='D'||a.duplicate_listing_of||a.status==='Duplicate listing'||a.duplicate_applications.length)return false;
  if(state.hosted){
    // Undated leads remain researchable; never label them as confirmed fresh.
    if(j.freshness==='older_than_48_hours'||j.freshness==='future_timestamp')return false;
    if(!j.global_remote&&!j.remote&&!/remote/i.test(j.location||''))return false;
  }
  return !isFreshRemote(j)||j.publication_verified_original!==true||a.tier==='C'||a.compensation?.status!=='meets_floor';
}
function activeJobs(){return state.jobs.filter(j=>!j.hidden&&isFreshRemote(j)&&j.open&&['A','B'].includes(j.assessment.tier)&&j.assessment.compensation?.status==='meets_floor'&&!['Archive','Duplicate listing'].includes(j.assessment.status)&&!j.assessment.duplicate_applications.length).sort((a,b)=>b.assessment.score-a.assessment.score)}
function title(over,heading,sub,action=''){return `<div class="title-row"><div><div class="overline">${esc(over)}</div><h1>${esc(heading)}</h1><div class="subtle">${esc(sub)}</div></div>${action}</div>`}
function jobCard(j){const a=j.assessment,publicationBadge=state.hosted&&j.publication_verified_original!==true?badge(j.source_posted_at&&j.within_discovery_window?'Source listing within 48h · original date unverified':'Employer publication date unverified','warn'):'';return `<article class="job"><div class="company-mark">${esc(j.company[0])}</div><div><span class="overline">${esc(j.company)}</span><h3>${esc(j.title)}</h3><p>${esc(j.location)} · ${esc(a.salary)}</p><div class="row">${badge(a.status,a.tier==='D'?'bad':a.tier==='C'?'warn':'')}${badge('Tier '+a.tier)}${publicationBadge}<small>Source checked ${esc(date(j.verified))}</small></div></div><div class="job-right"><div class="score">${a.score}<small>FIT / 100</small></div><div class="job-actions"><button data-job="${esc(j.id)}">Review ↗</button>${appliedButton(j)}${j.hidden?(j.hidden_role?'<button class="quiet" data-show-role="'+esc(j.id)+'">Unhide role</button>':'')+(j.hidden_employer?'<button class="quiet" data-show-employer="'+esc(j.id)+'">Unhide employer</button>':''):'<button class="quiet" data-hide-role="'+esc(j.id)+'">Hide role</button><button class="quiet" data-hide-employer="'+esc(j.id)+'">Hide employer</button>'}</div></div></article>`}
function overview(){const jobs=activeJobs(),verification=state.jobs.filter(j=>needsVerification(j)),priorities=jobs.filter(j=>j.assessment.score>=85&&j.assessment.compensation?.status==='meets_floor'),runs=[...(state.cloud_runs||[]),...(state.orchestration?.runs||[])];return title('Your career workspace','Your search, moving forward.',state.hosted?'International remote roles, verified original publication within 48 hours, and source-backed application drafts.':'Six bounded agents. Verified evidence. Your approval before employer actions.',`<button class="primary" id="run-full">${state.hosted?'Find fresh remote roles':'Run the agent workflow'} ↗</button>`)+`<div class="metrics"><div class="metric highlight"><label>Salary-qualified priorities</label><strong>${priorities.length}</strong><small>Verified pay at or above $2,500/month</small></div><div class="metric"><label>Applications tracked</label><strong>${state.applications.length}</strong><small>Preserved with event history</small></div><div class="metric"><label>Drafts awaiting review</label><strong>${state.packages.filter(p=>!p.hidden&&p.status==='review').length}</strong><small>Earlier versions retained separately</small></div><div class="metric"><label>Agent workflow runs</label><strong>${runs.length}</strong><small>${runs[0]?esc(runs[0].status):'Ready for the first run'}</small></div></div><div class="hero"><div class="panel hero-panel"><div class="overline">A more intentional search</div><h2>Let the agents prepare. Keep the decisions.</h2><p>${state.hosted?(state.desktop_runner?.standing_authorization?'The Mac worker can submit qualifying supported applications under your standing authorization. Missing facts and security challenges pause the affected role.':'Discovery and matching execute here. Application materials can be prepared on demand. The Mac application worker is not connected.'):'Discovery, matching and application materials share a recorded workflow. Inspect each stage to see what actually executed.'}</p></div><div class="panel"><div class="overline">Your non-negotiables</div><div class="check"><span>Minimum compensation</span><strong>$2,500 / month</strong></div><div class="check"><span>Unknown pay</span>${badge('Research · approval blocked','warn')}</div><div class="check"><span>Employer actions</span>${badge('Exact approval required')}</div><div class="check"><span>Audit chain</span>${badge(state.audit_valid?'Verified':'Check required',state.audit_valid?'':'bad')}</div></div></div>${discoverySummary()}${notificationPanel()}<div class="section-head"><h2>Opportunities to investigate</h2><button class="quiet" data-view="opportunities">View all records →</button><button class="quiet" data-filter-view="verification">Investigate unverified leads (${verification.length}) →</button></div><div class="stack">${jobs.slice(0,3).map(jobCard).join('')||'<div class="empty">No roles meet every confirmed eligibility, pay and freshness check. Open the unverified leads above to inspect what still needs evidence.</div>'}</div><div class="section-head"><h2>What runs automatically</h2><button class="quiet" data-view="agents">View agents & schedule →</button></div><div class="panel">${(state.schedule?.slots||[]).map(x=>`<div class="check"><strong>${esc(x.time)} WAT${x.weekday===4?' · Friday':''}</strong><span>${esc(x.label)}</span></div>`).join('')}</div><p class="note">${state.hosted?'Cloud discovery is scheduled. Source outlines, application drafts and reports run when requested. Automatic application submission is not connected.':'Local runner: work executes here. Scheduled Codex runs require this computer and Codex to be available.'} Google status: ${esc(state.connection_status?.mode||'Connection not verified')}. ${esc(state.connection_status?.blocker||'')}</p>`}

function latestScanIds(){const run=(state.cloud_runs||[]).find(r=>r.kind==='hosted_discovery');return new Set(state.discovery_audit?.observed_job_ids||run?.observed_job_ids||state.jobs.filter(j=>j.verified===run?.started).map(j=>j.id))}
function opportunities(){let jobs=state.jobs.filter(j=>(filter==='hidden'?j.hidden:!j.hidden)&&(!query||`${j.company} ${j.title} ${j.location}`.toLowerCase().includes(query.toLowerCase()))&&(filter==='all'||filter==='hidden'&&j.hidden||filter==='scan'&&latestScanIds().has(j.id)||filter==='recent'&&!j.assessment.duplicate_applications.length&&j.assessment.role_relevant!==false&&j.open&&j.remote&&j.within_discovery_window===true||filter==='active'&&isFreshRemote(j)&&j.open&&['A','B'].includes(j.assessment.tier)&&j.assessment.compensation?.status==='meets_floor'&&!['Archive','Duplicate listing'].includes(j.assessment.status)&&!j.assessment.duplicate_applications.length||filter==='verification'&&needsVerification(j)||filter==='excluded'&&j.assessment.tier==='D'||filter==='applied'&&j.assessment.duplicate_applications.length)).sort((a,b)=>b.assessment.score-a.assessment.score);return title('Search with evidence','Opportunities','Browse recent remote leads separately from confirmed eligibility and pay. Status labels show what still needs review.',`<button id="discover" class="primary">Refresh employer feeds ↻</button>`)+`<div class="filters"><input id="search" aria-label="Search opportunities" placeholder="Search role, company, or location" value="${esc(query)}"><select id="filter" aria-label="Filter opportunities">${[['recent','Recent remote posts · HR & people'],['scan','Latest scan · visible records'],['active','Verified eligibility & salary · ≤48h'],['verification','Leads · verify date, location or pay'],['all','All visible records'],['hidden','Hidden roles · manage'],['excluded','Excluded by eligibility'],['applied','Previously applied']].map(([v,l])=>`<option value="${v}" ${filter===v?'selected':''}>${l}</option>`).join('')}</select></div>${discoverySummary()}<p class="subtle">${jobs.length} records in this filter · ${state.jobs.length} saved in total · ${state.jobs.filter(j=>j.hidden).length} hidden · source-post dates and employer-original dates are shown separately</p><div class="stack">${jobs.map(jobCard).join('')||'<div class="empty">No matching records.</div>'}</div>`}
function pipeline(){const rows=state.applications.filter(a=>!query||`${a.company} ${a.role} ${a.status}`.toLowerCase().includes(query.toLowerCase()));return title('Your history, preserved','Application pipeline','Separate roles and application events remain separate records.',link(state.resources.sheet_url,'Open Google tracker'))+`<p class="note">${state.tracker?.status==='connected'?'Google tracker connected: manually recorded applications sync automatically.':'Google tracker authorization is required for automatic Sheet updates. HUNT still saves your application here.'}</p><div class="filters"><input id="search" placeholder="Search applications" aria-label="Search applications" value="${esc(query)}"></div><div class="table-wrap"><table><thead><tr><th>Company / role</th><th>First application</th><th>Status</th><th>Latest evidence</th><th>Source</th></tr></thead><tbody>${rows.map(a=>`<tr><td><strong>${esc(a.company)}</strong>${esc(a.role)}</td><td>${esc(a.applied||'Unknown')}</td><td>${badge(a.status,a.status==='Rejected'?'bad':'')}</td><td>${esc(a.latest)}<p class="subtle">${esc(a.notes)}</p></td><td>${a.evidence?link(a.evidence,'Evidence'):'<small>Owner reported · no receipt supplied</small>'}${a.submission_receipt?'<details><summary>Employer confirmation</summary><p>'+esc(a.submission_receipt.confirmation_text)+'</p><small>On-page receipt · email not verified<br>Reference: '+esc(a.submission_receipt.confirmation_id)+'</small></details>':''}${a.tracker_sync?'<p class="subtle">Google tracker: '+esc(a.tracker_sync.status==='synced'?'Synced':a.tracker_sync.reason||a.tracker_sync.status)+'</p>'+(a.tracker_sync.status!=='synced'?'<button class="quiet" data-sync-application="'+esc(a.id)+'">'+(a.tracker_sync.status==='uncertain'?'Recheck tracker':'Sync tracker')+'</button>':''):''}</td></tr>`).join('')}</tbody></table></div>`}
function studio(){return title('From evidence to a conversation','Application studio','Review the role, source facts, gaps, and final wording. Research drafts are separate from sendable approved actions.')+`<div class="note">${state.desktop_runner?.standing_authorization?'Standing authorization is active: available Lever applications can proceed on your awake Mac without per-application approval. Open a draft to inspect the exact CV and source evidence.':'The application worker is not connected. Open a package to inspect the preserved full CV and source evidence.'}</div><div class="stack spacer">${state.packages.filter(p=>!p.hidden&&p.status!=='superseded').map(p=>`<article class="job"><div class="company-mark">✧</div><div><div class="overline">${esc(p.company)}</div><h3>${esc(p.role)}</h3><p>${esc(p.generation)}</p>${badge(p.status)}</div><button data-package="${esc(p.id)}">Open package ↗</button></article>`).join('')||'<div class="empty">Choose an eligible opportunity to prepare your first application package.</div>'}</div>`}
function evidence(){return title('A source behind every claim','Your evidence bank','Verified against the master CV. No inferred metrics, qualifications, or employers.',link(state.resources.cv_url,'Master CV'))+`<div class="cards">${state.facts.map(f=>`<article class="fact"><code>${esc(f.id)}</code><p>${esc(f.text)}</p>${link(f.source,'Source CV')}</article>`).join('')}</div><div class="panel spacer"><h2>Your verified resources</h2><p>${esc(state.resources.email)}</p><div class="row">${link(state.resources.portfolio,'Portfolio')}${link(state.resources.linkedin,'LinkedIn')}${link(state.resources.sheet_url,'Tracker')}</div><p class="subtle">Source snapshot verified ${esc(date(state.resources.verified_at))}. LinkedIn is a supplied profile URL; no automated profile scraping is used.</p></div>`}
function activity(){return title('Transparent by design','Activity & connections','Source errors stay visible. A failed refresh never erases previously verified records.')+`<div class="panel"><h2>Connection status</h2>${Object.entries(state.capabilities).map(([k,v])=>`<div class="check"><strong>${esc(k)}</strong><span>${esc(v)}</span></div>`).join('')}</div><div class="section-head"><h2>Employer feeds</h2></div><div class="cards">${state.sources.map(s=>`<article class="fact"><div class="status-line"><h3>${esc(s.id)}</h3>${badge(s.status,s.status==='error'?'bad':'')}</div><p>${s.count} posting records · ${esc(date(s.at))}</p><small>${esc(s.error||(/^(remoteok|wwr|remotive|jobicy):/.test(s.id)?'Public job-board feed read; employer eligibility and original publication still require verification.':'Employer ATS feed read; individual role eligibility and publication evidence are shown per role.'))}</small></article>`).join('')}</div><div class="section-head"><h2>Audit trail</h2>${badge(state.audit_valid?'Hash chain valid':'Integrity check failed',state.audit_valid?'':'bad')}</div><div class="panel">${state.events.map(e=>`<div class="activity-row"><time>${esc(date(e.at))}</time><div><strong>${esc(e.kind.replaceAll('_',' '))}</strong><p class="subtle">${esc(e.payload)}</p></div></div>`).join('')}</div>`}
function desktopRunnerPanel(){const r=state.desktop_runner,fresh=r?.last_seen&&Date.now()-Date.parse(r.last_seen)<180000;return '<div class="panel spacer" id="desktop-runner-panel"><h2>Applications on your Mac</h2><p>'+esc(fresh?'Mac connected · '+r.status:'Mac runner not currently connected')+'</p><p>'+esc(r?.message||'Waiting for the local runner.')+'</p><p class="subtle">'+(r?.standing_authorization?'Standing authorization active. ':'')+(r?.selection==='all_unhidden_unapplied'?'Processing the whole unhidden, unapplied pool. ':'')+'Channels: '+esc((r?.providers||['lever']).map(p=>({lever:'Lever',breezy:'Breezy',html:'Other accessible forms',email:'Posting-specified email'}[p]||p)).join(', '))+'. Each job is processed separately; a blocked job does not stop the pool.'+(r?.last_seen?' Last check: '+esc(date(r.last_seen)):'')+'</p>'+Object.entries(r?.outcome_counts||{}).map(([s,n])=>'<p>'+esc(s.replaceAll('_',' '))+': '+n+'</p>').join('')+(r?.attempts||[]).slice(-20).reverse().map(a=>'<p>'+esc(a.company+' · '+a.role+' · '+a.status.replaceAll('_',' '))+'<br><span class="subtle">'+esc(a.message)+'</span></p>').join('')+'</div>'}
function agents(){const runs=[...(state.cloud_runs||[]),...(state.orchestration?.runs||[])];return title('Work you can inspect','Agents & operating schedule','Each agent has a bounded responsibility, permitted tools, persistent task state and recorded results.',`<button class="primary" id="run-full">${state.hosted?'Discover & rank fresh roles':'Run full workflow'}</button>`)+desktopRunnerPanel()+`<div class="cards">${(state.orchestration?.roles||[]).map(r=>`<article class="fact"><h3>${esc(r.id.replaceAll('_',' '))}</h3><p>Tools: ${r.tools.map(esc).join(', ')}</p>${state.hosted?'<p class=\"subtle\">'+esc(({discovery:'Runs in the hosted app.',match_intelligence:'Runs with hosted discovery.',application_studio:'Source outlines and AI drafts run on demand.',company_research:'Independent hosted employer research is not connected.',outreach:'Separate email draft is prepared with AI application packages. Nothing sends.',pipeline_intelligence:'Hosted Gmail connection is not configured; saved evidence remains available.'})[r.id]||'Availability requires verification')+'</p>':''}<small>Depends on: ${r.dependencies.map(esc).join(', ')||'No prior agent'}</small></article>`).join('')}</div><div class="row spacer"><button data-trigger="discovery">Discovery</button><button data-trigger="shortlist">${state.hosted?'Refresh discovery & ranking':'Prepare shortlist'}</button>${state.hosted?'<span class="note">Live inbox check unavailable: hosted Gmail is not connected.</span>':'<button data-trigger="pipeline">Check pipeline</button>'}</div><div class="section-head"><h2>Schedule · Africa/Lagos</h2></div><div class="panel">${(state.schedule?.slots||[]).map(x=>`<div class="check"><strong>${esc(x.time)}${x.weekday===4?' · Friday':''}</strong><span>${esc(x.label)}</span></div>`).join('')}<p class="subtle">${esc(state.schedule?.requirement||'Schedule execution is not yet verified.')}</p></div><div class="section-head"><h2>Workflow history</h2></div><div class="stack">${runs.map(r=>`<article class="job"><div class="company-mark">◈</div><div><h3>${esc(r.trigger||r.kind||'Agent run')}</h3><p>${esc(date(r.created||r.started))}</p>${badge(r.status,r.status==='blocked'?'warn':'')}</div><button data-run-id="${esc(r.id)}">Inspect tasks</button></article>`).join('')||'<p class="empty">No recorded workflow runs yet.</p>'}</div>`}
function reports(){return title('Outcomes, not activity volume','Reports & next actions','Imported evidence is the basis for these counts. An acknowledgement or rejection is never counted as an interview.',`<div class="row"><button data-report="daily">Daily report</button><button data-report="weekly">Weekly report</button></div>`)+`<div class="stack">${(state.reports||[]).map(r=>`<article class="panel"><div class="overline">${esc(r.period)} · ${esc(date(r.at))}</div><h2>${r.applications_total} applications · ${r.salary_qualified_priorities} qualified priorities</h2><p>${r.interview_invitations_observed} interview invitations observed · ${r.offers_observed} offers observed</p><h3>Recommended pipeline actions</h3>${(r.pipeline_next_actions||[]).map(a=>`<p class="note">${esc(a.kind)} · ${esc(a.application_id)} · ${esc(a.due)}</p>`).join('')||'<p class="subtle">No next-action records in this report.</p>'}<div class="subtle">${(r.limitations||[]).map(esc).join('<br>')}</div></article>`).join('')||'<div class="empty">Run a daily or weekly report to inspect your current pipeline.</div>'}</div><div class="section-head"><h2>Separate outreach drafts</h2></div><div class="stack">${(state.outreach||[]).map(o=>`<article class="panel"><h3>${esc(o.subject)}</h3>${badge(o.status,'warn')}<pre>${esc(o.body)}</pre><p class="subtle">${esc(o.limitation||'Nothing sent.')}</p></article>`).join('')||'<p class="subtle">Outreach drafts are prepared for qualified application packages. Recipient verification is separate.</p>'}</div>`}

function appendApolloContact(){
  if($('#apollo-contact-panel'))return;
  const panel=document.createElement('section');panel.id='apollo-contact-panel';panel.className='panel spacer';
  const ready=String(state.capabilities?.apollo||'').includes('configured')&&!String(state.capabilities?.apollo||'').includes('not configured');
  panel.innerHTML='<div class="overline">Application research</div><h2>Find a recruiter or hiring lead</h2><p class="subtle">'+esc(state.capabilities?.apollo||'Apollo connection status unavailable.')+' Search returns LinkedIn profiles and an email-availability indicator, not email addresses. No contact is messaged.</p><div class="filters"><select id="apollo-job" aria-label="Job for Apollo contact search">'+state.jobs.filter(j=>j.open).map(j=>'<option value="'+esc(j.id)+'">'+esc(j.company+' · '+j.title)+'</option>').join('')+'</select><input id="apollo-domain" aria-label="Employer domain" placeholder="company.com" autocomplete="url"><button id="apollo-search" '+(!ready?'disabled title="Configure APOLLO_API_KEY as a private server secret first"':'')+'>Search Apollo · 0 credits</button></div><div id="apollo-results" aria-live="polite">'+(!ready?'<p class="subtle">Apollo API is not connected. Add the key as a private server secret; never paste it here.</p>':'')+'</div>';
  $('#content').append(panel);
  const button=$('#apollo-search'),results=$('#apollo-results');
  button.onclick=async()=>{if(actionPending)return;const jobId=$('#apollo-job').value,companyDomain=$('#apollo-domain').value.trim();if(!jobId||!companyDomain){notify('Choose a job and enter the employer website domain.',true);return}actionPending=true;button.disabled=true;notify('Searching Apollo for matching professional profiles…');try{const data=await api('apollo/contacts',{job_id:jobId,company_domain:companyDomain});results.innerHTML=data.contacts.map(person=>`<article class="fact"><h3>${esc(person.first_name)} ${esc(person.last_name_obfuscated)}</h3><p>${esc(person.title)} · ${esc(person.organization||data.company)}</p>${person.linkedin_url?link(person.linkedin_url,'LinkedIn profile'):''}<p class="subtle">${person.has_email?'Apollo indicates an email may be available; search did not reveal it.':'No email availability indicated.'}</p></article>`).join('')||'<p class="subtle">No matching profiles found for this employer domain.</p>';notify(data.message)}catch(error){notify(error.message,true)}finally{actionPending=false;button.disabled=false}};
}

function render(){if(!state)return;$('#breadcrumb').textContent='Workspace / '+({overview:'Overview',opportunities:'Opportunities',pipeline:'Applications',studio:'Application studio',evidence:'Evidence bank',activity:'Activity & sources',agents:'Agents & schedule',reports:'Reports & next actions'}[view]);$('#pause').textContent=state.paused?'Resume HUNT':'Pause HUNT';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#content').innerHTML=({overview,opportunities,pipeline,studio,evidence,activity,agents,reports}[view])();if(view==='overview'&&state.hosted){const subtitle=$('#content .title-row .subtle');if(subtitle)subtitle.textContent='Recent remote listings from connected sources. Source-post and employer-original dates are shown separately.';const recentCount=state.jobs.filter(j=>!j.hidden&&j.assessment.role_relevant!==false&&j.open&&j.remote&&j.within_discovery_window).length,verify=$('#content [data-filter-view="verification"]');if(verify){const button=document.createElement('button');button.dataset.filterView='recent';button.textContent='Recent remote posts ('+recentCount+') →';verify.before(button)}const empty=$('#content .empty');if(empty)empty.textContent='No confirmed priorities. Review recent remote posts even when eligibility, pay or original dates still need verification.'}bind();if(view==='reports'&&state.hosted)appendApolloContact();}
const inlineQueues=new Map();
function appliedRecord(job){return (state.applications||[]).find(a=>a.job_id===job.id&&a.recorded_by==='owner')}
function appliedButton(job){const own=appliedRecord(job),applied=job.inline_applied??(!!own||!!job.assessment?.duplicate_applications?.length);return '<button class="quiet" data-mark-applied="'+esc(job.id)+'" aria-pressed="'+applied+'" '+(applied&&!own?'disabled':'')+' title="'+(own?'Undo applied mark':'Mark as applied')+'">'+(applied?'✓ Applied':'Mark as applied')+'</button>'}
function queueInline(key,task){const next=(inlineQueues.get(key)||Promise.resolve()).catch(()=>{}).then(task);inlineQueues.set(key,next);next.finally(()=>{if(inlineQueues.get(key)===next)inlineQueues.delete(key)}).catch(()=>{});return next}
function toggleApplied(id){
 const job=state.jobs.find(j=>j.id===id);if(!job||state.public_view)return;
 const old=appliedRecord(job),applied=!(job.inline_applied??!!old),record={id:'pending-'+id,job_id:id,company:job.company,role:job.title,recorded_by:'owner',status:'Application reported',applied:new Date(Date.now()+3600000).toISOString().slice(0,10),tracker_sync:{status:'pending'}};
 job.inline_applied=applied;
 if(applied)state.applications.push(record);else state.applications=state.applications.filter(a=>a!==old);
 document.querySelectorAll('[data-mark-applied]').forEach(b=>{if(b.dataset.markApplied===id){b.textContent=applied?'✓ Applied':'Mark as applied';b.setAttribute('aria-pressed',String(applied));b.title=applied?'Undo applied mark':'Mark as applied'}});
 queueInline('application:'+id,async()=>{try{const saved=await api('applications/applied',{job_id:id,applied,confirmed:true,applied_date:record.applied,defer_sync:true});if(applied&&saved.application){const index=state.applications.indexOf(record);if(index>=0)state.applications[index]=saved.application;}const appId=saved.application?.id||saved.application_id;if(appId)await api('tracker/sync',{application_id:appId});}catch(e){notify('Could not confirm this update: '+e.message+' Reload to check its saved state.',true)}});
}
function toggleVisibility(id,scope,hidden){
 const job=state.jobs.find(j=>j.id===id);if(!job||state.public_view)return;
 const employerKey=s=>String(s||'').toLowerCase().replace(/&/g,' and ').replace(/[^a-z0-9]+/g,' ').replace(/\b(?:incorporated|inc|limited|ltd|llc|plc)\b/g,'').trim().replace(/\s+/g,' ');
 const affected=state.jobs.filter(j=>scope==='employer'?employerKey(j.company)===employerKey(job.company):j.id===id),previous=affected.map(j=>({...j}));
 affected.forEach(j=>{j[scope==='employer'?'hidden_employer':'hidden_role']=hidden;j.hidden=!!(j.hidden_employer||j.hidden_role)});render();
 queueInline('visibility',async()=>{try{await api('job-visibility',{scope,hidden,job_id:id})}catch(e){previous.forEach(old=>Object.assign(state.jobs.find(j=>j.id===old.id),old));render();notify('Could not save visibility: '+e.message,true)}});
}
function jobDetail(id){const j=state.jobs.find(j=>j.id===id),a=j.assessment;$('#detail-content').innerHTML=`<div class="overline">${esc(j.company)} · Tier ${a.tier}</div><h1>${esc(j.title)}</h1><p>${esc(j.location)}</p><div class="row">${badge(a.status)}${badge(a.score+'/100 heuristic fit')}${badge(a.confidence+' confidence')}</div><div class="detail-block"><h3>Eligibility & compensation</h3><ul>${a.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>${a.duplicate_applications.length?'<p>This company and role already appear in your application history. A new posting does not authorize reapplication.</p>':''}</div><div class="detail-block"><h3>Transparent score</h3>${Object.entries(a.components).map(([k,v])=>`<div class="check"><span>${esc(k.replaceAll('_',' '))}</span><strong>${v} points</strong></div>`).join('')}<p class="subtle">Weights follow the PRD: skills 30%, eligibility 25%, compensation 15%, progression 15%, company 10%, preferences 5%. Missing evidence earns no confirmed points.</p></div>${a.semantic_evidence?`<div class="detail-block"><h3>AI semantic review · source-grounded inference</h3>${a.semantic_evidence.requirements.map(r=>`<p>“${esc(r.job_quote)}”<br><small>Candidate evidence: ${r.fact_ids.length?r.fact_ids.map(esc).join(", "):"Not established"}</small></p>`).join("")}<p class="subtle">${esc(a.semantic_evidence.limitation)}</p></div>`:""}<h2>Evidence trail</h2>${a.matches.map(m=>`<div class="trace"><h3>${esc(m.criterion)}</h3><p>Employer: “${esc(m.job_quote)}”</p><p>Your evidence: ${esc(m.candidate_evidence)}</p>${link(m.source,'Verified CV fact '+m.fact_id)}</div>`).join('')}<div class="detail-block"><h3>Posting dates</h3><p>Original publication: ${esc(j.publication_verified_original?date(j.published):'Not verified')}${j.last_published?'<br>ATS last republished: '+esc(date(j.last_published)):''}${j.board_published?'<br>Board listing published: '+esc(date(j.board_published)):''}<br>Updated: ${esc(date(j.updated))}<br>First discovered: ${esc(date(j.discovered))}<br>Source last checked: ${esc(date(j.verified))}</p><p class="subtle">${esc(j.publication_source||'The source did not supply a verified employer-original date.')} A recent source check is not proof of a recent publication date.</p>${link(j.url,j.source_attribution?'Listing on '+j.source_attribution:'Employer posting')}${j.original_application_url?link(j.original_application_url,'Employer application page'):''}</div><details class="detail-block"><summary>Full employer job description</summary><pre>${esc(j.description)}</pre></details><div class="row">${a.tier!=='D'&&!a.duplicate_applications.length&&j.open?`<button class="primary" data-prepare="${esc(j.id)}">Prepare with AI ✧</button><button data-excerpt="${esc(j.id)}">Prepare source excerpts</button>`:'<p class="note">Application preparation is blocked for excluded or previously applied roles.</p>'}</div>`;if(!$('#detail').open)if(!$('#detail').open)$('#detail').showModal();bind();}
async function packageDetail(id){let p=state.packages.find(p=>p.id===id);if(state.hosted){try{p=await api('package?id='+encodeURIComponent(id))}catch(error){notify(error.message,true);return}}if(!p){notify('Package is not available yet. Refresh the studio.',true);return;}$('#detail-content').innerHTML=`<div class="overline">Application package · ${esc(p.status)}</div><h1>${esc(p.company)}</h1><p>${esc(p.role)}</p><div class="note">${p.review_note?esc(p.review_note)+'<br>':''}${p.limitations.map(esc).join('<br>')}</div><div class="row spacer">${p.full_cv_preserved&&p.payload_hash?`<button class="primary" data-download-cv="${esc(p.id)}" data-package-hash="${esc(p.payload_hash)}">Download CV · ${p.native_cv?'PDF':'Word'}</button>`:''}<button data-download="${esc(p.id)}">Download package data</button>${state.hosted&&!["superseded","rejected"].includes(p.status)?`<button data-edit-package="${esc(p.id)}">Edit draft</button>`:``}${p.native_cv?.document_url?link(p.native_cv.document_url,'Open tailored Google Doc'):''}${link(p.application_url,'Review employer posting')}</div><div class="detail-block"><h3>Company research</h3><p>${esc(p.company_dossier.hypothesis)}</p>${p.company_dossier.operational_needs_excerpts.map(x=>`<p>“${esc(x)}”</p>`).join('')}<p>Hiring manager: ${esc(p.company_dossier.hiring_manager)}</p><p>${esc(p.company_dossier.funding_and_recent_news)}</p>${link(p.company_dossier.source,'Research source')}</div><div class="detail-block"><h3>${p.full_cv_preserved?'Full CV · preserved content':'Verified evidence outline · not a full CV'}</h3><pre>${esc(p.resume_full||p.resume_excerpt)}</pre></div><div class="detail-block"><h3>Cover letter · draft</h3><pre>${esc(p.cover_letter)}</pre>${p.cold_email?`<h3>Separate cold email · ${esc(p.cold_email_subject||'Draft')}</h3><pre>${esc(p.cold_email)}</pre>`:''}<p class="subtle">Recipient: unverified. No email address inferred.</p></div><div class="detail-block"><h3>Application answers</h3>${Object.entries(p.answers).map(([k,v])=>`<h3>${esc(k)}</h3><pre>${esc(v)}</pre>`).join('')}</div><div class="detail-block"><h3>Interview practice</h3><ul>${p.interview_questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul></div><div class="row"><button class="primary" data-approve="${esc(p.id)}" ${['requires_revision','superseded','rejected'].includes(p.status)?'disabled':''}>Mark draft reviewed (optional)</button><button data-reject="${esc(p.id)}">Reject package</button></div><p class="subtle">${state.desktop_runner?.standing_authorization?'Draft review is optional. The Mac worker uses standing authorization, current eligibility evidence and exact CV checks before supported form submissions.':'The Mac worker is not connected. Draft review alone does not submit an application.'}</p>`;if(!$('#detail').open)$('#detail').showModal();bind();}
async function editPackage(id){
  try{
    const p=await api('package?id='+encodeURIComponent(id));editingPackage=p;
    const fields=[['cover_letter','Cover letter',p.cover_letter],['cold_email_subject','Email subject',p.cold_email_subject],['cold_email','Cold email',p.cold_email],['cv_summary_draft','CV professional summary',p.cv_summary_draft]];
    $('#detail-content').innerHTML='<h1>Edit application draft</h1><p>All employment, qualifications and projects are preserved. Saving creates a new review version and sends nothing.</p>'+fields.map(([key,label,value])=>'<label class="detail-block">'+label+'<textarea id="edit-'+key+'" rows="'+(key==='cold_email_subject'?2:8)+'" style="width:100%">'+esc(value||'')+'</textarea></label>').join('')+'<label>Revision notes<textarea id="edit-review_notes" rows="3" style="width:100%"></textarea></label><button class="primary" id="save-revision">Save new review version</button>';
    $('#save-revision').onclick=e=>action(e.target,async()=>{
      const body={package_id:p.id,expected_payload_hash:p.payload_hash,claim_fact_ids:p.claim_fact_ids||p.facts.map(f=>f.id),review_notes:$('#edit-review_notes').value};
      for(const [key] of fields)body[key]=$('#edit-'+key).value;
      const saved=await api('package/revision',body);await refresh();await packageDetail(saved.id);return {message:'New draft version saved. Earlier versions remain in history. Nothing sent.'};
    });
    if(!$('#detail').open)$('#detail').showModal();
  }catch(e){notify(e.message,true)}
}
function setActionControls(disabled){document.querySelectorAll('#discover,#run-full,#pause,[data-trigger],[data-report],[data-prepare],[data-excerpt],[data-approve],[data-reject],[data-download],[data-apollo-search],[data-mark-applied],[data-sync-application],[data-hide-role],[data-hide-employer],[data-show-role],[data-show-employer]').forEach(b=>{if(disabled){if(b.dataset.disabledBeforeAction===undefined)b.dataset.disabledBeforeAction=b.disabled?'true':'false';b.disabled=true}else if(b.dataset.disabledBeforeAction!==undefined){b.disabled=b.dataset.disabledBeforeAction==='true';delete b.dataset.disabledBeforeAction}})}
async function action(button,fn){
 if(state?.public_view){notify('Owner access is required.',true);return}
 if(actionPending){notify('An action is already running. Its saved result will appear when it finishes.');return}
 actionPending=true;setActionControls(true);button.disabled=true;notify('Starting in HUNT…');
 try{const result=await waitForDiscovery(await fn());let reloadError=null;try{await refresh()}catch(e){reloadError=e}
  const message=operationMessage(result)+(reloadError?' The operation returned a saved result, but the dashboard reload failed. Reload the page to view it.':'');
  notify(message,!!(reloadError||result?.queued||['queued','blocked','failed','running'].includes(result?.status)));
 }catch(e){notify(e.name==='TimeoutError'||e.name==='AbortError'?'Status could not be confirmed. A cloud run may still be active; check Activity before starting another.':e.message,true)}
 finally{actionPending=false;setActionControls(false);button.disabled=false}
}


function download(name,data){const blob=new Blob([data],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function publicViewControls(){if(!state?.public_view)return;document.querySelectorAll('#discover,#run-full,#pause,[data-trigger],[data-report],[data-prepare],[data-excerpt],[data-approve],[data-reject],[data-edit-package],#save-revision').forEach(b=>{b.disabled=true;b.title='Owner-only control. Public visitors can view the live workspace.'});const tag=document.querySelector('.local-tag');if(tag)tag.textContent='● Public · live workspace';}
async function downloadCV(button){
 const label=button.textContent;button.disabled=true;button.textContent='Preparing CV…';
 try{const r=await fetch('/api/cv-artifact?id='+encodeURIComponent(button.dataset.downloadCv)+'&hash='+encodeURIComponent(button.dataset.packageHash),{signal:AbortSignal.timeout(30000)});if(!r.ok){const error=await r.json();throw Error(error.error||'CV download failed')}const bytes=await r.arrayBuffer(),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');if(hash!==r.headers.get('X-HUNT-Artifact-SHA256'))throw Error('CV download integrity check failed');const name=/filename="([^"]+)"/.exec(r.headers.get('Content-Disposition')||'')?.[1]||'CV.docx',blob=new Blob([bytes],{type:r.headers.get('Content-Type')}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){notify(e.message,true)}finally{button.textContent=label;button.disabled=false}
}
function bind(){document.querySelectorAll('[data-download-cv]').forEach(b=>b.onclick=()=>downloadCV(b));document.querySelectorAll('[data-mark-applied]').forEach(b=>b.onclick=()=>toggleApplied(b.dataset.markApplied));document.querySelectorAll('[data-sync-application]').forEach(b=>b.onclick=()=>action(b,()=>api('tracker/sync',{application_id:b.dataset.syncApplication})));for(const [attr,scope,hidden]of [['hide-role','job',true],['hide-employer','employer',true],['show-role','job',false],['show-employer','employer',false]])document.querySelectorAll('[data-'+attr+']').forEach(b=>b.onclick=()=>toggleVisibility(b.getAttribute('data-'+attr),scope,hidden));document.querySelectorAll('[data-edit-package]').forEach(b=>b.onclick=()=>editPackage(b.dataset.editPackage));document.querySelectorAll('[data-filter-view]').forEach(b=>b.onclick=()=>{view='opportunities';filter=b.dataset.filterView;query='';render()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;query='';render()});document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>jobDetail(b.dataset.job));document.querySelectorAll('[data-package]').forEach(b=>b.onclick=()=>packageDetail(b.dataset.package));for(const [attr,useAI]of [['prepare',true],['excerpt',false]])document.querySelectorAll(`[data-${attr}]`).forEach(b=>b.onclick=()=>action(b,async()=>{const p=await api('package',{job_id:b.dataset[attr],use_ai:useAI});if(p.queued||p.status==='queued')return {...p,message:p.message||'This request is waiting for the connected runner. It has not completed.'};await refresh();await packageDetail(p.id);return {message:p.message||'Package prepared from verified facts. Review the source evidence and wording.'}}));for(const[attr,decision]of [['approve','approved_for_manual_action'],['reject','rejected']])document.querySelectorAll(`[data-${attr}]`).forEach(b=>b.onclick=()=>action(b,async()=>{const r=await api('review',{package_id:b.dataset[attr],decision});$('#detail').close();return r}));document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>action(b,async()=>{const p=state.hosted?await api('package?id='+encodeURIComponent(b.dataset.download)):state.packages.find(p=>p.id===b.dataset.download);if(!p)throw Error('Package not found');download('HUNT-application-package.json',JSON.stringify(p,null,2));return {message:'Downloaded the complete reviewed package, including the full CV when available.'}}));if($('#discover'))$('#discover').onclick=e=>action(e.target,()=>api('run',{trigger:'discovery'}));if($('#run-full'))$('#run-full').onclick=e=>action(e.target,()=>api('run',{trigger:'full'}));document.querySelectorAll('[data-trigger]').forEach(b=>b.onclick=()=>action(b,()=>api('run',{trigger:b.dataset.trigger})));document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>action(b,()=>api('report',{period:b.dataset.report})));document.querySelectorAll('[data-run-id]').forEach(b=>b.onclick=async()=>{try{const saved=(state.cloud_runs||[]).find(r=>r.id===b.dataset.runId);const r=saved?{...saved,tasks:[{role:'hosted_discovery_and_matching',status:saved.status,result:saved}]}:await api('workflow?id='+encodeURIComponent(b.dataset.runId));$('#detail-content').innerHTML='<h1>Agent workflow</h1><div class=note>'+esc(r.status)+'</div>'+r.tasks.map(t=>'<div class=detail-block><h3>'+esc(t.role.replaceAll('_',' '))+'</h3><p>'+esc(t.status)+'</p><pre>'+esc(JSON.stringify(t.result,null,2))+'</pre></div>').join('');$('#detail').showModal()}catch(e){notify(e.message,true)}});if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;render()};if(actionPending)setActionControls(true);publicViewControls()}
$('#close').onclick=()=>$('#detail').close();$('#pause').onclick=e=>action(e.target,()=>api('pause',{paused:!state.paused}));$('#export').onclick=()=>download('HUNT-workspace-private.json',JSON.stringify(state,null,2));
(async()=>{try{const token=location.hash.slice(1);if(token){history.replaceState(null,'','/');await api('login',{token})}await refresh();resumeDiscoveryProgress()}catch(e){notify(e.message,true);$('#content').innerHTML='<h1>Your private workspace</h1><p>Sign in through your private HUNT site. For the local workspace, open Start HUNT.command.</p>'}})();

setInterval(()=>{if(state&&!actionPending&&!document.querySelector('dialog[open]'))refresh().catch(()=>{});},15000);

setInterval(async()=>{if(!state?.hosted||state.public_view||!document.querySelector('#desktop-runner-panel'))return;try{state.desktop_runner=await api('application-runner-status');document.querySelector('#desktop-runner-panel').outerHTML=desktopRunnerPanel()}catch{}},30000);
